 if(btn.id==='copySeatsBtn'){const order=getSeating(),c=activeClass(),{cols,rows}=seatingLayout(c,order.length);const lines=Array.from({length:rows},(_,row)=>Array.from({length:cols},(_,col)=>{const i=row*cols+col;return `${i+1}번 ${order[i]?nameOf(order[i]):'빈 자리'}`;}).join(' | '));return copyText(`${c.name} 자리 배치 (${cols}열 × ${rows}줄)\n${lines.join('\n')}`);}
 if(btn.dataset.seatIndex!==undefined){const i=Number(btn.dataset.seatIndex),c=activeClass();if(selectedSeat===null){selectedSeat=i;render();return;}if(selectedSeat===i){selectedSeat=null;render();return;}const order=getSeating();[order[i],order[selectedSeat]]=[order[selectedSeat],order[i]];c.seating=order;selectedSeat=null;save();render();toast('두 자리를 맞바꿨습니다.');return;}
