 if(btn.id==='exportParticipationBtn'){const c=activeClass();download(`${safeFilename(c.name)}_참여기록.csv`,csv([['학생 이름','참여 횟수','참여 여부'],...c.students.map(s=>[s.name,s.points,s.included===false?'제외':'참여'])]),'text/csv;charset=utf-8');toast('참여 기록 CSV를 저장했습니다.');return;}
