function printList(heading,lines){const popup=window.open('','_blank','width=680,height=800');if(!popup)return toast('인쇄 팝업이 차단되었습니다.');popup.document.write(`<!doctype html><html lang="ko"><meta charset="utf-8"><title>${escapeHtml(heading)}</title><style>body{font-family:sans-serif;padding:32px}h1{font-size:23px}li{font-size:18px;line-height:2}</style><h1>${escapeHtml(heading)}</h1><ol>${lines.map(line=>`<li>${escapeHtml(line.replace(/^\d+\.\s*/,''))}</li>`).join('')}</ol></html>`);popup.document.close();popup.focus();setTimeout(()=>popup.print(),350);}
function onSubmit(event){event.preventDefault();const form=event.target;if(form.id==='addOneForm'){const val=$('#studentName').value;addStudents(val);}if(form.id==='addBulkForm'){const val=$('#bulkNames').value;addStudents(val);}if(form.id==='renameClassForm'){const val=$('#className').value.trim().slice(0,60);if(!val)return toast('학급 이름을 입력해 주세요.');activeClass().name=val;save();renderAll();toast('학급 이름을 변경했습니다.');}}
function onChange(event){const el=event.target;if(currentView==='secret'&&el.id==='secretMode'){secretMode(el.value);return;}if(currentView==='notice'&&!noticePresenting){if(el.dataset.noticeField!==undefined){noticeFieldChange(el);return;}const n=activeNotice();if(el.id==='notice-color'&&['green','black','navy'].includes(el.value)){n.color=el.value;save();render();return;}if(el.id==='notice-size'&&['normal','large','extra'].includes(el.value)){n.size=el.value;save();render();return;}if(el.id==='notice-ruled'){n.ruled=el.checked;save();render();return;}}if(el.id==='boardDaySelect'){boardDay=Number(el.value);render();return;}if(el.id==='activeClassSelect'){secretLeave();if(noticePresenting)noticeStopPresentation();lunchCancelAnimation();lunchRecentId=null;if(gradingFullScreen){gradingFullScreen=false;document.body.classList.remove('grading-fullscreen');}if(boardPresenting)stopBoardPresentation();cancelRace();raceResultVisible=false;state.activeClassId=el.value;resetPickerState(true);lastPickedId=null;selectedSeat=null;save();renderAll();}if(el.id==='themeSelect'){setUiTheme(el.value);return;}if(el.id==='restoreFile')restore(el.files?.[0]);if(el.id==='groupCount'){groupCount=Number(el.value);}if(el.id==='seatCols'||el.id==='seatRows'){const c=activeClass();if(el.id==='seatCols')c.seatingCols=clamp(Number(el.value)||5,3,8);else c.seatingRows=clamp(Number(el.value)||6,3,12);selectedSeat=null;save();render();}}
document.addEventListener('click',onClick);document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);document.addEventListener('input',event=>{if(currentView==='secret'&&event.target.id==='secretMissionList')secretMissionEdit(event.target.value);if(currentView==='dashboard'&&!boardPresenting)boardFieldInput(event.target);if(currentView==='notice'&&!noticePresenting&&noticeFieldChange(event.target)){const n=activeNotice();const preview=document.querySelector('.notice-chalk-preview');if(preview){const tmp=document.createElement('div');tmp.innerHTML=noticeBoardMarkup(true);preview.replaceWith(tmp.firstElementChild);}}});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&boardPresenting){boardPresenting=false;document.body.classList.remove('board-presenting');render();}if(!document.fullscreenElement&&noticePresenting){noticePresenting=false;document.body.classList.remove('notice-presenting');render();}});setInterval(refreshBoardClock,15000);document.addEventListener('keydown',event=>{if(boardPresenting&&event.code==='Escape'){event.preventDefault();stopBoardPresentation();return;}if(noticePresenting&&event.code==='Escape'){event.preventDefault();noticeStopPresentation();return;}if(currentView==='secret'&&secretOpenId&&event.code==='Escape'){secretMask();render();return;}if(currentView==='race'&&!raceRunning&&event.code==='Space'&&!/input|textarea|button|select/i.test(event.target.tagName)){event.preventDefault();startRace();}});
boot();